// Frequently asked questions in every site language. {memory}, {cpu} and {size} come from site-config.js.
window.AO_LEGAL = {
en: { title: 'Frequently asked questions', intro: ['Short answers to what people ask most. Something missing? I’d be glad to hear it in the <a href="index.html#feedback">feedback section</a>.'], questions: [
  { q: 'Which AI tools does it work with?', a: ['Claude Code, Codex and Cursor. Claude Code and Codex chats are read from their own records on your computer; an optional connection in Settings adds live status and questions. Cursor joins through its optional hooks. Answering a question from the office depends on what the source tool supports.'] },
  { q: 'Does The Agent Office approve anything on its own?', a: ['No. It never approves a question, a tool permission or a command for you. It shows what is waiting and opens the source tool, so the decision stays yours.'] },
  { q: 'Which Windows versions are supported?', a: ['Windows 10 and Windows 11, 64-bit.'] },
  { q: 'How much does it use?', a: ['About {memory} of memory while running and {cpu} CPU when nothing moves; the installer is {size}. These are approximate figures from our own measurements.'] },
  { q: 'Is it free?', a: ['Yes, The Agent Office is free to use. Support is voluntary and unlocks nothing extra.'] },
  { q: 'Where is my data kept?', a: ['Only on your computer, in the app’s own data folder under <code>%LOCALAPPDATA%</code>. Nothing goes to a server of ours; the <a href="privacy.html">privacy policy</a> lists every request the app makes.'] },
  { q: 'How can I remove it cleanly?', a: ['Classic installer: uninstalling from Settings › Apps also removes The Agent Office’s own entries from Claude Code, Codex and Cursor and its small helper.', 'Microsoft Store version: Windows cannot run that clean-up, so it is best to choose Disconnect for each connected tool in The Agent Office’s Settings first, then uninstall. Your other settings are never touched.'] },
  { q: 'Does it work without AI tools?', a: ['Yes. Media controls, notes, timers, alarms and water tracking work on their own.'] },
  { q: 'How can I reach you or report a bug?', a: ['Bugs are best reported on <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. For anything else, write to <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> or on Telegram <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
tr: { title: 'Sık sorulan sorular', intro: ['En çok sorulanlara kısa yanıtlar. Eksik bir şey varsa <a href="index.html#feedback">geri bildirim bölümünden</a> yazarsan sevinirim.'], questions: [
  { q: 'Hangi yapay zekâ araçlarıyla çalışıyor?', a: ['Claude Code, Codex ve Cursor. Claude Code ve Codex sohbetleri bilgisayarındaki kendi kayıtlarından okunur; Ayarlar’daki isteğe bağlı bağlantı canlı durum ve soruları ekler. Cursor isteğe bağlı hook’larıyla katılır. Ofisten bir soruyu yanıtlamak, kaynak aracın neyi desteklediğine bağlıdır.'] },
  { q: 'The Agent Office kendi başına bir şeyi onaylıyor mu?', a: ['Hayır. Bir soruyu, araç iznini ya da komutu asla senin yerine onaylamaz. Bekleyeni gösterir ve kaynak aracı açar; karar her zaman sende kalır.'] },
  { q: 'Hangi Windows sürümleri destekleniyor?', a: ['Windows 10 ve Windows 11, 64 bit.'] },
  { q: 'Ne kadar kaynak kullanıyor?', a: ['Çalışırken yaklaşık {memory} bellek, hiçbir şey hareket etmezken {cpu} işlemci; kurulum dosyası {size}. Bunlar kendi ölçümlerimizden yaklaşık değerler.'] },
  { q: 'Ücretsiz mi?', a: ['Evet, The Agent Office’i kullanmak ücretsiz. Destek gönüllüdür ve ek bir şey açmaz.'] },
  { q: 'Verilerim nerede tutuluyor?', a: ['Yalnız bilgisayarında, uygulamanın <code>%LOCALAPPDATA%</code> altındaki kendi veri klasöründe. Bizim bir sunucumuza hiçbir şey gitmez; uygulamanın yaptığı her istek <a href="privacy.html">gizlilik politikasında</a> yazılı.'] },
  { q: 'Temiz bir şekilde nasıl kaldırılır?', a: ['Klasik kurulum: Ayarlar › Uygulamalar’dan kaldırınca The Agent Office’in Claude Code, Codex ve Cursor’a eklediği kendi girdileri ve küçük yardımcı programı da silinir.', 'Microsoft Store sürümü: Windows bu temizliği çalıştıramadığı için önce The Agent Office Ayarlar’ında bağlı her araç için Bağlantıyı kaldır’ı seçip sonra kaldırmak en iyisi. Diğer ayarlarına hiç dokunulmaz.'] },
  { q: 'Yapay zekâ araçları olmadan da çalışır mı?', a: ['Evet. Medya kontrolleri, notlar, zamanlayıcılar, alarmlar ve su takibi kendi başına çalışır.'] },
  { q: 'Sana nasıl ulaşabilirim, bir hatayı nasıl bildirebilirim?', a: ['Hataları <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a> üzerinden bildirmek en kolayı. Diğer her şey için <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> adresine ya da Telegram’da <a href="https://t.me/eyrafx">@eyrafx</a> hesabına yazabilirsin.'] },
] },
es: { title: 'Preguntas frecuentes', intro: ['Respuestas breves a lo que más se pregunta. ¿Falta algo? Me encantará leerlo en la <a href="index.html#feedback">sección de comentarios</a>.'], questions: [
  { q: '¿Con qué herramientas de IA funciona?', a: ['Claude Code, Codex y Cursor. Los chats de Claude Code y Codex se leen de sus propios registros en tu ordenador; una conexión opcional en Ajustes añade estado en vivo y preguntas. Cursor se suma con sus hooks opcionales. Responder a una pregunta desde la oficina depende de lo que admita la herramienta de origen.'] },
  { q: '¿The Agent Office aprueba algo por su cuenta?', a: ['No. Nunca aprueba una pregunta, un permiso de herramienta ni un comando por ti. Muestra lo que espera y abre la herramienta de origen; la decisión sigue siendo tuya.'] },
  { q: '¿Qué versiones de Windows admite?', a: ['Windows 10 y Windows 11, 64 bits.'] },
  { q: '¿Cuántos recursos usa?', a: ['Unos {memory} de memoria en marcha y {cpu} de CPU cuando nada se mueve; el instalador ocupa {size}. Son cifras aproximadas de nuestras propias mediciones.'] },
  { q: '¿Es gratis?', a: ['Sí, usar The Agent Office es gratis. El apoyo es voluntario y no desbloquea nada extra.'] },
  { q: '¿Dónde se guardan mis datos?', a: ['Solo en tu ordenador, en la carpeta de datos de la app dentro de <code>%LOCALAPPDATA%</code>. Nada va a un servidor nuestro; la <a href="privacy.html">política de privacidad</a> enumera cada petición que hace la app.'] },
  { q: '¿Cómo se desinstala sin dejar rastro?', a: ['Instalador clásico: al desinstalar desde Configuración › Aplicaciones también se quitan las entradas propias de The Agent Office en Claude Code, Codex y Cursor y su pequeño asistente.', 'Versión de Microsoft Store: Windows no puede ejecutar esa limpieza, así que lo mejor es elegir primero Desconectar para cada herramienta conectada en los Ajustes de The Agent Office y después desinstalar. Tus demás ajustes nunca se tocan.'] },
  { q: '¿Funciona sin herramientas de IA?', a: ['Sí. Los controles multimedia, notas, temporizadores, alarmas y el registro de agua funcionan por sí solos.'] },
  { q: '¿Cómo puedo contactarte o informar de un error?', a: ['Los errores se informan mejor en <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. Para lo demás, escribe a <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> o por Telegram a <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
de: { title: 'Häufige Fragen', intro: ['Kurze Antworten auf das, was am häufigsten gefragt wird. Fehlt etwas? Ich freue mich über eine Nachricht im <a href="index.html#feedback">Feedback-Bereich</a>.'], questions: [
  { q: 'Mit welchen KI-Tools funktioniert es?', a: ['Claude Code, Codex und Cursor. Chats von Claude Code und Codex werden aus deren eigenen Protokollen auf deinem Computer gelesen; eine optionale Verbindung in den Einstellungen ergänzt Live-Status und Fragen. Cursor kommt über seine optionalen Hooks dazu. Ob sich eine Frage im Büro beantworten lässt, hängt vom Ursprungstool ab.'] },
  { q: 'Genehmigt The Agent Office etwas von selbst?', a: ['Nein. Es genehmigt nie eine Frage, eine Tool-Berechtigung oder einen Befehl für dich. Es zeigt, was wartet, und öffnet das Ursprungstool – die Entscheidung bleibt bei dir.'] },
  { q: 'Welche Windows-Versionen werden unterstützt?', a: ['Windows 10 und Windows 11, 64 Bit.'] },
  { q: 'Wie viel verbraucht es?', a: ['Etwa {memory} Arbeitsspeicher im Betrieb und {cpu} CPU, wenn sich nichts bewegt; das Installationsprogramm hat {size}. Das sind ungefähre Werte aus eigenen Messungen.'] },
  { q: 'Ist es kostenlos?', a: ['Ja, The Agent Office ist kostenlos nutzbar. Unterstützung ist freiwillig und schaltet nichts frei.'] },
  { q: 'Wo werden meine Daten gespeichert?', a: ['Nur auf deinem Computer, im Datenordner der App unter <code>%LOCALAPPDATA%</code>. Nichts geht an einen Server von uns; die <a href="privacy.html">Datenschutzerklärung</a> listet jede Anfrage der App auf.'] },
  { q: 'Wie lässt es sich sauber entfernen?', a: ['Klassischer Installer: Beim Deinstallieren über Einstellungen › Apps werden auch die eigenen Einträge von The Agent Office in Claude Code, Codex und Cursor sowie sein kleines Hilfsprogramm entfernt.', 'Microsoft-Store-Version: Windows kann diese Bereinigung nicht ausführen, daher am besten zuerst in den Einstellungen von The Agent Office bei jedem verbundenen Tool Trennen wählen und danach deinstallieren. Deine übrigen Einstellungen bleiben immer unberührt.'] },
  { q: 'Funktioniert es auch ohne KI-Tools?', a: ['Ja. Mediensteuerung, Notizen, Timer, Wecker und Wasserprotokoll funktionieren eigenständig.'] },
  { q: 'Wie erreiche ich dich oder melde einen Fehler?', a: ['Fehler meldest du am besten über <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. Für alles andere schreib an <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> oder auf Telegram an <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
fr: { title: 'Questions fréquentes', intro: ['Des réponses courtes aux questions les plus fréquentes. Il manque quelque chose ? Je serais ravi de le lire dans la <a href="index.html#feedback">section des retours</a>.'], questions: [
  { q: 'Avec quels outils d’IA fonctionne-t-il ?', a: ['Claude Code, Codex et Cursor. Les chats de Claude Code et Codex sont lus depuis leurs propres journaux sur ton ordinateur ; une connexion facultative dans les Réglages ajoute l’état en direct et les questions. Cursor se joint via ses hooks facultatifs. Répondre à une question depuis le bureau dépend de ce que l’outil d’origine permet.'] },
  { q: 'The Agent Office approuve-t-il quelque chose tout seul ?', a: ['Non. Il n’approuve jamais une question, une autorisation d’outil ou une commande à ta place. Il montre ce qui attend et ouvre l’outil d’origine ; la décision reste la tienne.'] },
  { q: 'Quelles versions de Windows sont prises en charge ?', a: ['Windows 10 et Windows 11, 64 bits.'] },
  { q: 'Quelles ressources utilise-t-il ?', a: ['Environ {memory} de mémoire en fonctionnement et {cpu} de processeur au repos ; l’installateur pèse {size}. Ce sont des valeurs approximatives issues de nos propres mesures.'] },
  { q: 'Est-ce gratuit ?', a: ['Oui, The Agent Office est gratuit. Le soutien est volontaire et ne débloque rien de plus.'] },
  { q: 'Où mes données sont-elles conservées ?', a: ['Uniquement sur ton ordinateur, dans le dossier de données de l’app sous <code>%LOCALAPPDATA%</code>. Rien ne part vers un serveur à nous ; la <a href="privacy.html">politique de confidentialité</a> liste chaque requête de l’app.'] },
  { q: 'Comment le désinstaller proprement ?', a: ['Installateur classique : la désinstallation depuis Paramètres › Applications retire aussi les entrées de The Agent Office dans Claude Code, Codex et Cursor ainsi que son petit utilitaire.', 'Version Microsoft Store : Windows ne peut pas lancer ce nettoyage, le mieux est donc de choisir d’abord Déconnecter pour chaque outil connecté dans les Réglages de The Agent Office, puis de désinstaller. Tes autres réglages ne sont jamais touchés.'] },
  { q: 'Fonctionne-t-il sans outils d’IA ?', a: ['Oui. Les commandes multimédias, notes, minuteurs, alarmes et le suivi de l’eau fonctionnent seuls.'] },
  { q: 'Comment te joindre ou signaler un bug ?', a: ['Les bugs se signalent au mieux sur <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. Pour le reste, écris à <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> ou sur Telegram à <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
'pt-BR': { title: 'Perguntas frequentes', intro: ['Respostas curtas para o que mais perguntam. Faltou algo? Vou adorar saber pela <a href="index.html#feedback">seção de feedback</a>.'], questions: [
  { q: 'Com quais ferramentas de IA ele funciona?', a: ['Claude Code, Codex e Cursor. Os chats do Claude Code e do Codex são lidos dos próprios registros no seu computador; uma conexão opcional nas Configurações adiciona status ao vivo e perguntas. O Cursor entra pelos hooks opcionais. Responder a uma pergunta pelo escritório depende do que a ferramenta de origem suporta.'] },
  { q: 'The Agent Office aprova algo sozinho?', a: ['Não. Ele nunca aprova uma pergunta, permissão de ferramenta ou comando por você. Mostra o que está esperando e abre a ferramenta de origem; a decisão continua sendo sua.'] },
  { q: 'Quais versões do Windows são suportadas?', a: ['Windows 10 e Windows 11, 64 bits.'] },
  { q: 'Quanto ele consome?', a: ['Cerca de {memory} de memória em uso e {cpu} de CPU quando nada se move; o instalador tem {size}. São valores aproximados das nossas próprias medições.'] },
  { q: 'É gratuito?', a: ['Sim, usar The Agent Office é gratuito. O apoio é voluntário e não libera nada extra.'] },
  { q: 'Onde meus dados ficam?', a: ['Só no seu computador, na pasta de dados do app em <code>%LOCALAPPDATA%</code>. Nada vai para um servidor nosso; a <a href="privacy.html">política de privacidade</a> lista cada solicitação que o app faz.'] },
  { q: 'Como remover sem deixar rastros?', a: ['Instalador clássico: desinstalar em Configurações › Aplicativos também remove as entradas de The Agent Office no Claude Code, Codex e Cursor e o pequeno auxiliar.', 'Versão da Microsoft Store: o Windows não consegue fazer essa limpeza, então o ideal é escolher antes Desconectar para cada ferramenta conectada nas Configurações de The Agent Office e depois desinstalar. Suas outras configurações nunca são tocadas.'] },
  { q: 'Funciona sem ferramentas de IA?', a: ['Sim. Controles de mídia, notas, timers, alarmes e registro de água funcionam sozinhos.'] },
  { q: 'Como falar com você ou relatar um bug?', a: ['Bugs são mais bem relatados no <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. Para o resto, escreva para <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> ou no Telegram para <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
it: { title: 'Domande frequenti', intro: ['Risposte brevi alle domande più comuni. Manca qualcosa? Sarò felice di leggerlo nella <a href="index.html#feedback">sezione feedback</a>.'], questions: [
  { q: 'Con quali strumenti di IA funziona?', a: ['Claude Code, Codex e Cursor. Le chat di Claude Code e Codex vengono lette dai loro registri sul tuo computer; un collegamento facoltativo nelle Impostazioni aggiunge stato in tempo reale e domande. Cursor si aggiunge con i suoi hook facoltativi. Rispondere a una domanda dall’ufficio dipende da ciò che supporta lo strumento di origine.'] },
  { q: 'The Agent Office approva qualcosa da solo?', a: ['No. Non approva mai una domanda, un permesso di uno strumento o un comando al posto tuo. Mostra ciò che è in attesa e apre lo strumento di origine; la decisione resta tua.'] },
  { q: 'Quali versioni di Windows sono supportate?', a: ['Windows 10 e Windows 11, 64 bit.'] },
  { q: 'Quante risorse usa?', a: ['Circa {memory} di memoria in esecuzione e {cpu} di CPU quando nulla si muove; il programma di installazione pesa {size}. Sono valori approssimativi delle nostre misurazioni.'] },
  { q: 'È gratuito?', a: ['Sì, The Agent Office è gratuito. Il supporto è volontario e non sblocca nulla in più.'] },
  { q: 'Dove sono conservati i miei dati?', a: ['Solo sul tuo computer, nella cartella dati dell’app in <code>%LOCALAPPDATA%</code>. Nulla va a un nostro server; l’<a href="privacy.html">informativa sulla privacy</a> elenca ogni richiesta dell’app.'] },
  { q: 'Come si rimuove in modo pulito?', a: ['Programma di installazione classico: disinstallando da Impostazioni › App vengono rimosse anche le voci di The Agent Office in Claude Code, Codex e Cursor e il suo piccolo programma di supporto.', 'Versione Microsoft Store: Windows non può eseguire questa pulizia, quindi conviene prima scegliere Scollega per ogni strumento collegato nelle Impostazioni di The Agent Office e poi disinstallare. Le altre impostazioni non vengono mai toccate.'] },
  { q: 'Funziona senza strumenti di IA?', a: ['Sì. Controlli multimediali, note, timer, sveglie e registro dell’acqua funzionano da soli.'] },
  { q: 'Come posso contattarti o segnalare un bug?', a: ['I bug si segnalano meglio su <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. Per tutto il resto, scrivi a <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> o su Telegram a <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
ru: { title: 'Частые вопросы', intro: ['Короткие ответы на самые частые вопросы. Чего-то не хватает? Буду рад прочитать об этом в <a href="index.html#feedback">разделе отзывов</a>.'], questions: [
  { q: 'С какими ИИ-инструментами он работает?', a: ['Claude Code, Codex и Cursor. Чаты Claude Code и Codex читаются из их собственных записей на вашем компьютере; необязательное подключение в настройках добавляет живой статус и вопросы. Cursor подключается через свои необязательные хуки. Можно ли ответить на вопрос из офиса, зависит от исходного инструмента.'] },
  { q: 'Одобряет ли The Agent Office что-то сам?', a: ['Нет. Он никогда не одобряет за вас вопрос, разрешение инструмента или команду. Он показывает, что ждёт, и открывает исходный инструмент — решение остаётся за вами.'] },
  { q: 'Какие версии Windows поддерживаются?', a: ['Windows 10 и Windows 11, 64-разрядные.'] },
  { q: 'Сколько ресурсов он использует?', a: ['Около {memory} памяти во время работы и {cpu} процессора в простое; установщик весит {size}. Это приблизительные значения по нашим замерам.'] },
  { q: 'Это бесплатно?', a: ['Да, The Agent Office бесплатный. Поддержка добровольна и ничего дополнительно не открывает.'] },
  { q: 'Где хранятся мои данные?', a: ['Только на вашем компьютере, в папке данных приложения в <code>%LOCALAPPDATA%</code>. Ничего не уходит на наш сервер; в <a href="privacy.html">политике конфиденциальности</a> перечислен каждый запрос приложения.'] },
  { q: 'Как удалить его начисто?', a: ['Классический установщик: при удалении через «Параметры › Приложения» также удаляются собственные записи The Agent Office в Claude Code, Codex и Cursor и его небольшой помощник.', 'Версия из Microsoft Store: Windows не может выполнить такую очистку, поэтому лучше сначала выбрать «Отключить» для каждого подключённого инструмента в настройках The Agent Office, а затем удалить приложение. Остальные ваши настройки не затрагиваются.'] },
  { q: 'Работает ли он без ИИ-инструментов?', a: ['Да. Управление медиа, заметки, таймеры, будильники и учёт воды работают сами по себе.'] },
  { q: 'Как с вами связаться или сообщить об ошибке?', a: ['Об ошибках удобнее всего сообщать в <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>. По остальным вопросам пишите на <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> или в Telegram <a href="https://t.me/eyrafx">@eyrafx</a>.'] },
] },
ja: { title: 'よくある質問', intro: ['よく寄せられる質問への短い答えです。足りないことがあれば、<a href="index.html#feedback">フィードバック欄</a>で教えていただけるとうれしいです。'], questions: [
  { q: 'どのAIツールに対応していますか？', a: ['Claude Code、Codex、Cursorです。Claude CodeとCodexのチャットはコンピューター上のそれぞれの記録から読み取り、設定の任意の接続でライブの状態と質問が加わります。Cursorは任意のフックで連携します。オフィスから質問に答えられるかどうかは、元のツールの対応状況によります。'] },
  { q: 'The Agent Officeが勝手に何かを承認することはありますか？', a: ['ありません。質問、ツールの許可、コマンドをあなたの代わりに承認することは決してありません。待っているものを表示し、元のツールを開くだけなので、判断はいつもあなたのものです。'] },
  { q: '対応しているWindowsのバージョンは？', a: ['Windows 10とWindows 11（64ビット）です。'] },
  { q: 'どれくらいリソースを使いますか？', a: ['動作中のメモリは約{memory}、何も動いていないときのCPUは{cpu}、インストーラーは{size}です。いずれも私たちの計測による概算値です。'] },
  { q: '無料ですか？', a: ['はい、The Agent Officeは無料で使えます。支援は任意で、追加機能が解放されることはありません。'] },
  { q: 'データはどこに保存されますか？', a: ['お使いのコンピューターの<code>%LOCALAPPDATA%</code>内にある、アプリのデータフォルダーだけです。私たちのサーバーには何も送られません。アプリが行う通信はすべて<a href="privacy.html">プライバシーポリシー</a>に記載しています。'] },
  { q: 'きれいにアンインストールするには？', a: ['通常版インストーラー: 「設定 › アプリ」からアンインストールすると、The Agent OfficeがClaude Code、Codex、Cursorに追加した項目と小さな補助プログラムも削除されます。', 'Microsoft Store版: Windowsはこの後片付けを実行できないため、先にThe Agent Officeの設定で接続中の各ツールの「切断」を選んでからアンインストールするのがおすすめです。他の設定に触れることはありません。'] },
  { q: 'AIツールがなくても使えますか？', a: ['はい。メディア操作、メモ、タイマー、アラーム、水分記録は単独で動作します。'] },
  { q: '連絡や不具合の報告はどうすればいいですか？', a: ['不具合は <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a> で報告していただくのがいちばん確実です。それ以外は <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> または Telegram の <a href="https://t.me/eyrafx">@eyrafx</a> までどうぞ。'] },
] },
ko: { title: '자주 묻는 질문', intro: ['가장 많이 묻는 질문에 대한 짧은 답입니다. 빠진 내용이 있다면 <a href="index.html#feedback">피드백 섹션</a>에서 알려 주시면 기쁘겠습니다.'], questions: [
  { q: '어떤 AI 도구와 함께 쓰나요?', a: ['Claude Code, Codex, Cursor입니다. Claude Code와 Codex 채팅은 컴퓨터에 있는 각 도구의 기록에서 읽고, 설정의 선택적 연결로 실시간 상태와 질문이 더해집니다. Cursor는 선택적 훅으로 함께합니다. 오피스에서 질문에 답할 수 있는지는 원래 도구의 지원 여부에 따라 다릅니다.'] },
  { q: 'The Agent Office가 스스로 무언가를 승인하나요?', a: ['아니요. 질문, 도구 권한, 명령을 사용자 대신 승인하는 일은 절대 없습니다. 기다리는 것을 보여 주고 원래 도구를 열어 줄 뿐이며, 결정은 언제나 사용자에게 있습니다.'] },
  { q: '어떤 Windows 버전을 지원하나요?', a: ['Windows 10과 Windows 11, 64비트입니다.'] },
  { q: '자원을 얼마나 쓰나요?', a: ['실행 중 메모리는 약 {memory}, 아무것도 움직이지 않을 때 CPU는 {cpu}, 설치 파일은 {size}입니다. 자체 측정에 따른 대략적인 값입니다.'] },
  { q: '무료인가요?', a: ['네, The Agent Office는 무료로 쓸 수 있습니다. 후원은 자발적이며 추가 기능이 열리지 않습니다.'] },
  { q: '데이터는 어디에 저장되나요?', a: ['사용자의 컴퓨터, <code>%LOCALAPPDATA%</code> 아래 앱 데이터 폴더에만 저장됩니다. 저희 서버로는 아무것도 가지 않으며, 앱이 하는 모든 요청은 <a href="privacy.html">개인정보 처리방침</a>에 적혀 있습니다.'] },
  { q: '깔끔하게 제거하려면?', a: ['일반 설치 프로그램: 설정 › 앱에서 제거하면 The Agent Office가 Claude Code, Codex, Cursor에 추가한 항목과 작은 도우미도 함께 지워집니다.', 'Microsoft Store 버전: Windows가 이 정리를 실행할 수 없으므로, 먼저 The Agent Office 설정에서 연결된 도구마다 연결 끊기를 선택한 뒤 제거하는 것이 가장 좋습니다. 다른 설정은 전혀 건드리지 않습니다.'] },
  { q: 'AI 도구 없이도 작동하나요?', a: ['네. 미디어 제어, 메모, 타이머, 알람, 물 기록은 단독으로 작동합니다.'] },
  { q: '연락하거나 버그를 신고하려면 어떻게 하나요?', a: ['버그는 <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>에 남겨 주시면 가장 좋습니다. 그 밖의 문의는 <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> 또는 텔레그램 <a href="https://t.me/eyrafx">@eyrafx</a>로 보내 주세요.'] },
] },
'zh-Hans': { title: '常见问题', intro: ['大家最常问的问题，简短回答。还缺什么？很高兴在<a href="index.html#feedback">反馈区</a>听到你的声音。'], questions: [
  { q: '它支持哪些 AI 工具？', a: ['Claude Code、Codex 和 Cursor。Claude Code 和 Codex 的聊天从它们在你电脑上的记录中读取；设置中的可选连接会加入实时状态和提问。Cursor 通过可选钩子接入。能否在办公室里回答问题，取决于来源工具的支持情况。'] },
  { q: 'The Agent Office 会自行批准什么吗？', a: ['不会。它从不替你批准问题、工具权限或命令。它只显示正在等待的内容并打开来源工具，决定权始终在你。'] },
  { q: '支持哪些 Windows 版本？', a: ['Windows 10 和 Windows 11，64 位。'] },
  { q: '它占用多少资源？', a: ['运行时内存约 {memory}，静止时 CPU 约 {cpu}，安装程序约 {size}。这些是我们自己测量的近似值。'] },
  { q: '免费吗？', a: ['是的，The Agent Office 可免费使用。支持完全自愿，不会解锁任何额外内容。'] },
  { q: '我的数据保存在哪里？', a: ['只保存在你的电脑上，位于 <code>%LOCALAPPDATA%</code> 下应用自己的数据文件夹。不会发送到我们的任何服务器；应用发出的每个请求都列在<a href="privacy.html">隐私政策</a>中。'] },
  { q: '如何干净地卸载？', a: ['经典安装版：在“设置 › 应用”中卸载时，也会移除 The Agent Office 添加到 Claude Code、Codex 和 Cursor 的条目及其小助手程序。', 'Microsoft Store 版：Windows 无法运行这项清理，所以最好先在 The Agent Office 设置中为每个已连接的工具选择“断开连接”，再卸载。你的其他设置不会被改动。'] },
  { q: '没有 AI 工具也能用吗？', a: ['可以。媒体控制、笔记、计时器、闹钟和饮水记录都能独立使用。'] },
  { q: '如何联系你或报告问题？', a: ['问题反馈最好提交到 <a href="https://github.com/eyrafx/agentoffice/issues">GitHub Issues</a>。其他事情请发邮件至 <a href="mailto:eyra@hotmail.com.tr">eyra@hotmail.com.tr</a> 或在 Telegram 联系 <a href="https://t.me/eyrafx">@eyrafx</a>。'] },
] },
};
